for n in range(2, 10):
    for d in range(2, n):
        if n % d == 0:
            break
    else:                      # runs only if no break
        print(n, end=" ")
print()
i = 0
while i < 5:
    i += 1
    if i == 3:
        continue
    print(i, end=" ")

def safe_div(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        print("cannot divide by zero")
        return None
    else:
        return result
    finally:
        print("done", a, b)

print(safe_div(8, 2))
print(safe_div(1, 0))
